import readline from 'readline/promises';
import axios from 'axios';

const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

const email = await rl.question('Email: ');
const send = await axios.post('https://am.neonode.my.id/api/send-link', { email });
console.log(send.data.message || send.data);

const magicLink = await rl.question('Link: ');
const verify = await axios.post('https://am.neonode.my.id/api/verify-link', { email, magicLink });
console.log(verify.data);

rl.close();

